char *ossl_buf2hexstr_sep(const unsigned char *buf, long buflen, char sep)
{
    char *tmp;
    size_t tmp_n;

    if (buflen < 0)
        return NULL;
    if (buflen == 0)
        return OPENSSL_zalloc(1);

    /* Check for overflow before multiplication */
    if (sep != CH_ZERO) {
        if (buflen > SIZE_MAX / 3)
            return NULL;
        tmp_n = buflen * 3;
    } else {
        if (buflen > (SIZE_MAX - 1) / 2)
            return NULL;
        tmp_n = 1 + buflen * 2;
    }

    if ((tmp = OPENSSL_malloc(tmp_n)) == NULL)
        return NULL;

    if (buf2hexstr_sep(tmp, tmp_n, NULL, buf, buflen, sep))
        return tmp;
    OPENSSL_free(tmp);
    return NULL;
}

static int rsasve_generate(PROV_RSA_CTX *prsactx,
    unsigned char *out, size_t *outlen,
    unsigned char *secret, size_t *secretlen)
{
    int ret;
    size_t nlen;

    /* Step (1): nlen = Ceil(len(n)/8) */
    nlen = RSA_size(prsactx->rsa);

    if (out == NULL) {
        if (nlen == 0) {
            ERR_raise(ERR_LIB_PROV, PROV_R_INVALID_KEY);
            return 0;
        }
        if (outlen == NULL && secretlen == NULL)
            return 0;
        if (outlen != NULL)
            *outlen = nlen;
        if (secretlen != NULL)
            *secretlen = nlen;
        return 1;
    }

    /*
     * If outlen is specified, then it must report the length
     * of the out buffer on input so that we can confirm
     * its size is sufficient for encapsulation
     */
    if (outlen != NULL && *outlen < nlen) {
        ERR_raise(ERR_LIB_PROV, PROV_R_INVALID_OUTPUT_LENGTH);
        return 0;
    }

    /*
     * Step (2): Generate a random byte string z of nlen bytes where
     *            1 < z < n - 1
     */
    if (!rsasve_gen_rand_bytes(prsactx->rsa, secret, (int)nlen))
        return 0;

    /* Step(3): out = RSAEP((n,e), z) */
    ret = RSA_public_encrypt((int)nlen, secret, out, prsactx->rsa,
        RSA_NO_PADDING);
    if (ret == (int)nlen) {
        ret = 1;
        if (outlen != NULL)
            *outlen = nlen;
        if (secretlen != NULL)
            *secretlen = nlen;
    } else {
        OPENSSL_cleanse(secret, nlen);
        ret = 0;
    }
    return ret;
}

static int PBMAC1_PBKDF2_HMAC(OSSL_LIB_CTX *ctx, const char *propq,
    const char *pass, int passlen,
    const X509_ALGOR *macalg, unsigned char *key)
{
    PBKDF2PARAM *pbkdf2_param = NULL;
    const ASN1_OBJECT *kdf_hmac_oid;
    int kdf_hmac_nid;
    int ret = -1;
    int keylen = 0;
    EVP_MD *kdf_md = NULL;
    const ASN1_OCTET_STRING *pbkdf2_salt = NULL;

    pbkdf2_param = PBMAC1_get1_pbkdf2_param(macalg);
    if (pbkdf2_param == NULL) {
        ERR_raise(ERR_LIB_PKCS12, ERR_R_UNSUPPORTED);
        goto err;
    }

    if (pbkdf2_param->prf == NULL) {
        kdf_hmac_nid = NID_hmacWithSHA1;
    } else {
        X509_ALGOR_get0(&kdf_hmac_oid, NULL, NULL, pbkdf2_param->prf);
        kdf_hmac_nid = OBJ_obj2nid(kdf_hmac_oid);
    }

    kdf_md = EVP_MD_fetch(ctx, OBJ_nid2sn(ossl_hmac2mdnid(kdf_hmac_nid)), propq);
    if (kdf_md == NULL) {
        ERR_raise(ERR_LIB_PKCS12, ERR_R_FETCH_FAILED);
        goto err;
    }

    /* Validate salt is an OCTET STRING choice */
    if (pbkdf2_param->salt == NULL
        || pbkdf2_param->salt->type != V_ASN1_OCTET_STRING) {
        ERR_raise_data(ERR_LIB_PKCS12, PKCS12_R_PARSE_ERROR, "Invalid Salt");
        goto err;
    }
    pbkdf2_salt = pbkdf2_param->salt->value.octet_string;

    /* Validate salt length is sufficient */
    if (pbkdf2_salt->length < 8) {
        ERR_raise_data(ERR_LIB_PKCS12, PKCS12_R_PARSE_ERROR,
            "Invalid Salt length (%d is not in the range 8..)", pbkdf2_salt->length);
        goto err;
    }

    /* RFC 9579 specifies missing key length as invalid */
    if (pbkdf2_param->keylength != NULL)
        keylen = ASN1_INTEGER_get(pbkdf2_param->keylength);
    if (keylen <= 0 || keylen > EVP_MAX_MD_SIZE) {
        ERR_raise_data(ERR_LIB_PKCS12, PKCS12_R_PARSE_ERROR,
            "Invalid Key length (%d is not in the range 1..64)", keylen);
        goto err;
    }

    if (PKCS5_PBKDF2_HMAC(pass, passlen, pbkdf2_salt->data, pbkdf2_salt->length,
            ASN1_INTEGER_get(pbkdf2_param->iter), kdf_md, keylen, key)
        <= 0) {
        ERR_raise(ERR_LIB_PKCS12, ERR_R_INTERNAL_ERROR);
        goto err;
    }
    ret = keylen;

err:
    EVP_MD_free(kdf_md);
    PBKDF2PARAM_free(pbkdf2_param);

    return ret;
}

static int depack_do_frame_path_challenge(PACKET *pkt,
    QUIC_CHANNEL *ch,
    OSSL_ACKM_RX_PKT *ackm_data)
{
    uint64_t frame_data = 0;
    unsigned char *encoded = NULL;
    size_t encoded_len;
    WPACKET wpkt;

    if (!ossl_quic_wire_decode_frame_path_challenge(pkt, &frame_data)) {
        ossl_quic_channel_raise_protocol_error(ch,
            OSSL_QUIC_ERR_FRAME_ENCODING_ERROR,
            OSSL_QUIC_FRAME_TYPE_PATH_CHALLENGE,
            "decode error");
        return 0;
    }

    /*
     * RFC 9000 s. 8.2.2: On receiving a PATH_CHALLENGE frame, an endpoint MUST
     * respond by echoing the data contained in the PATH_CHALLENGE frame in a
     * PATH_RESPONSE frame.
     *
     * TODO(QUIC FUTURE): We should try to avoid allocation here in the future.
     */
    if (ossl_quic_cfq_get_pending_count(ch->cfq) >= OSSL_QUIC_MAX_PENDING_PATH_RESPONSES) {
        ossl_quic_channel_raise_protocol_error(ch,
            OSSL_QUIC_ERR_INTERNAL_ERROR,
            OSSL_QUIC_FRAME_TYPE_PATH_CHALLENGE,
            "too many pending path responses");
        return 0;
    }

    encoded_len = sizeof(uint64_t) + 1;
    if ((encoded = OPENSSL_malloc(encoded_len)) == NULL)
        goto err;

    if (!WPACKET_init_static_len(&wpkt, encoded, encoded_len, 0))
        goto err;

    if (!ossl_quic_wire_encode_frame_path_response(&wpkt, frame_data)) {
        WPACKET_cleanup(&wpkt);
        goto err;
    }

    WPACKET_finish(&wpkt);

    if (!ossl_quic_cfq_add_frame(ch->cfq, 0, QUIC_PN_SPACE_APP,
            OSSL_QUIC_FRAME_TYPE_PATH_RESPONSE,
            QUIC_CFQ_ITEM_FLAG_UNRELIABLE,
            encoded, encoded_len,
            free_path_response, NULL))
        goto err;

    return 1;

err:
    OPENSSL_free(encoded);
    ossl_quic_channel_raise_protocol_error(ch, OSSL_QUIC_ERR_INTERNAL_ERROR,
        OSSL_QUIC_FRAME_TYPE_PATH_CHALLENGE,
        "internal error");
    return 0;
}

static int check_cert_ocsp_resp(X509_STORE_CTX *ctx)
{
    int cert_status, crl_reason;
    int i;
    OCSP_RESPONSE *resp = NULL;
    OCSP_BASICRESP *bs = NULL;
    OCSP_SINGLERESP *sr = NULL;
    OCSP_CERTID *sr_cert_id = NULL;
    ASN1_GENERALIZEDTIME *rev, *thisupd, *nextupd;
    ASN1_OBJECT *cert_id_md_oid;
    EVP_MD *cert_id_md = NULL;
    OCSP_CERTID *cert_id = NULL;
    int ret = V_OCSP_CERTSTATUS_UNKNOWN;
    int num;

    num = sk_OCSP_RESPONSE_num(ctx->ocsp_resp);

    if (num < 0 || num <= ctx->error_depth)
        return X509_V_ERR_OCSP_NO_RESPONSE;

    if ((resp = sk_OCSP_RESPONSE_value(ctx->ocsp_resp, ctx->error_depth)) == NULL
        || (bs = OCSP_response_get1_basic(resp)) == NULL
        || (num = OCSP_resp_count(bs)) < 1)
        return X509_V_ERR_OCSP_NO_RESPONSE;

    if (OCSP_response_status(resp) != OCSP_RESPONSE_STATUS_SUCCESSFUL) {
        ret = X509_V_ERR_OCSP_RESP_INVALID;
        goto end;
    }

    if (OCSP_basic_verify(bs, ctx->chain, ctx->store, 0) <= 0) {
        ret = X509_V_ERR_OCSP_SIGNATURE_FAILURE;
        goto end;
    }

    /* find the right single response in the OCSP response */
    for (i = 0; i < num; i++) {
        sr = OCSP_resp_get0(bs, i);

        /* determine the md algorithm which was used to create cert id */
        sr_cert_id = (OCSP_CERTID *)OCSP_SINGLERESP_get0_id(sr);
        OCSP_id_get0_info(NULL, &cert_id_md_oid, NULL, NULL, sr_cert_id);
        if (cert_id_md_oid != NULL) {
            char md_name[80];

            if (i2t_ASN1_OBJECT(md_name, sizeof(md_name), cert_id_md_oid) > 0)
                cert_id_md = EVP_MD_fetch(ctx->libctx, md_name, ctx->propq);
        }

        /* search the stack for the requested OCSP response */
        cert_id = OCSP_cert_to_id(cert_id_md, ctx->current_cert, ctx->current_issuer);
        EVP_MD_free(cert_id_md);
        cert_id_md = NULL;
        if (cert_id == NULL) {
            ret = X509_V_ERR_OCSP_RESP_INVALID;
            goto end;
        }

        if (!OCSP_id_cmp(cert_id, sr_cert_id))
            break;

        OCSP_CERTID_free(cert_id);
        cert_id = NULL;
    }

    if (cert_id == NULL) {
        ret = X509_V_ERR_OCSP_NO_RESPONSE;
        goto end;
    }

    if (OCSP_resp_find_status(bs, cert_id, &cert_status, &crl_reason, &rev,
            &thisupd, &nextupd)
        <= 0) {
        ret = X509_V_ERR_OCSP_RESP_INVALID;
        goto end;
    }

    if (cert_status == V_OCSP_CERTSTATUS_GOOD) {
        /*
         * Note:
         * A OCSP stapling result will be accepted up to 5 minutes
         * after it expired!
         */
        if (!OCSP_check_validity(thisupd, nextupd, 300L, -1L))
            ret = X509_V_ERR_OCSP_HAS_EXPIRED;
        else
            ret = V_OCSP_CERTSTATUS_GOOD;
    } else {
        ret = cert_status;
    }

end:
    OCSP_CERTID_free(cert_id);
    OCSP_BASICRESP_free(bs);
    return ret;
}

static int setup_dp(const X509 *x, DIST_POINT *dp)
{
    const X509_NAME *iname = NULL;
    int i;

    if (dp->distpoint == NULL && sk_GENERAL_NAME_num(dp->CRLissuer) <= 0) {
        ERR_raise(ERR_LIB_X509, X509_R_INVALID_DISTPOINT);
        return 0;
    }
    if (dp->reasons != NULL) {
        if (dp->reasons->length > 0)
            dp->dp_reasons = dp->reasons->data[0];
        if (dp->reasons->length > 1)
            dp->dp_reasons |= (dp->reasons->data[1] << 8);
        dp->dp_reasons &= CRLDP_ALL_REASONS;
    } else {
        dp->dp_reasons = CRLDP_ALL_REASONS;
    }
    if (dp->distpoint == NULL || dp->distpoint->type != 1)
        return 1;

    /* Handle name fragment given by nameRelativeToCRLIssuer */
    /*
     * Note that the below way of determining iname is not really compliant
     * with https://tools.ietf.org/html/rfc5280#section-4.2.1.13
     * According to it, sk_GENERAL_NAME_num(dp->CRLissuer) MUST be <= 1
     * and any CRLissuer could be of type different to GEN_DIRNAME.
     */
    for (i = 0; i < sk_GENERAL_NAME_num(dp->CRLissuer); i++) {
        GENERAL_NAME *gen = sk_GENERAL_NAME_value(dp->CRLissuer, i);

        if (gen->type == GEN_DIRNAME) {
            iname = gen->d.directoryName;
            break;
        }
    }
    if (iname == NULL)
        iname = X509_get_issuer_name(x);

    /* Defer DIST_POINT_set_dpname() processing to avoid excessive memory allocation during certificate caching */
    dp->dpname = NULL;
    return 1;
}

QUIC_NEEDS_LOCK
int ossl_quic_handle_frames(QUIC_CHANNEL *ch, OSSL_QRX_PKT *qpacket)
{
    PACKET pkt;
    OSSL_ACKM_RX_PKT ackm_data;
    uint32_t enc_level;
    size_t pkt_len = qpacket->hdr->len;

    if (ch == NULL)
        return 0;

    ossl_ch_reset_rx_state(ch);

    /* Initialize |ackm_data| (and reinitialize |ok|)*/
    memset(&ackm_data, 0, sizeof(ackm_data));
    /*
     * ASSUMPTION: All packets that aren't special case have a
     * packet number.
     */
    ackm_data.pkt_num = qpacket->pn;
    ackm_data.time = qpacket->time;
    enc_level = ossl_quic_pkt_type_to_enc_level(qpacket->hdr->type);
    if (enc_level >= QUIC_ENC_LEVEL_NUM)
        /*
         * Retry and Version Negotiation packets should not be passed to this
         * function.
         */
        return 0;

    ackm_data.pkt_space = ossl_quic_enc_level_to_pn_space(enc_level);

    /*
     * RFC 9000 s. 8.1
     * We can consider the connection to be validated, if we receive a packet
     * from the client protected via handshake keys, meaning that the
     * amplification limit no longer applies (i.e. we can set it as validated.
     * Otherwise, add the size of this packet to the unvalidated credit for
     * the connection.
     */
    if (enc_level == QUIC_ENC_LEVEL_HANDSHAKE)
        ossl_quic_tx_packetiser_set_validated(ch->txp);
    else
        ossl_quic_tx_packetiser_add_unvalidated_credit(ch->txp, pkt_len);

    /* Now that special cases are out of the way, parse frames */
    if (!PACKET_buf_init(&pkt, qpacket->hdr->data, qpacket->hdr->len)
        || !depack_process_frames(ch, &pkt, qpacket,
            enc_level,
            qpacket->time,
            &ackm_data))
        return 0;

    ossl_ackm_on_rx_packet(ch->ackm, &ackm_data);

    return 1;
}

static int check_revocation(X509_STORE_CTX *ctx)
{
    int i = 0, last = 0, ok = 0;
    int crl_check_enabled = (ctx->param->flags & X509_V_FLAG_CRL_CHECK) != 0;
    int crl_check_all_enabled = crl_check_enabled && (ctx->param->flags & X509_V_FLAG_CRL_CHECK_ALL) != 0;
    int ocsp_check_enabled = (ctx->param->flags & X509_V_FLAG_OCSP_RESP_CHECK) != 0;
    int ocsp_check_all_enabled = ocsp_check_enabled && (ctx->param->flags & X509_V_FLAG_OCSP_RESP_CHECK_ALL) != 0;

    if (!crl_check_enabled && !ocsp_check_enabled)
        return 1;

    if (ocsp_check_enabled) {
#ifndef OPENSSL_NO_OCSP
        /*
         * certificate status checking with OCSP
         */
        if (ocsp_check_all_enabled)
            last = sk_X509_num(ctx->chain) - 1;
        else if (!crl_check_all_enabled && ctx->parent != NULL)
            return 1; /* If checking CRL paths this isn't the EE certificate */

        for (i = 0; i <= last; i++) {
            ctx->error_depth = i;
            ctx->current_cert = sk_X509_value(ctx->chain, i);

            /* skip if cert is apparently self-signed */
            if (ctx->current_cert->ex_flags & EXFLAG_SS)
                continue;

            /* the issuer certificate is the next in the chain */
            ctx->current_issuer = sk_X509_value(ctx->chain, i + 1);

            /* skip if there is no issuer certificate */
            if (ctx->current_issuer == NULL)
                continue;

            ok = check_cert_ocsp_resp(ctx);

            /*
             * In the case the certificate status is REVOKED, the verification
             * can stop here.
             */
            if (ok == V_OCSP_CERTSTATUS_REVOKED) {
                return verify_cb_ocsp(ctx, ctx->error != 0 ? ctx->error : X509_V_ERR_OCSP_VERIFY_FAILED);
            }

            /*
             * In the case the certificate status is GOOD, continue with the next
             * certificate.
             */
            if (ok == V_OCSP_CERTSTATUS_GOOD)
                continue;

            /*
             * As stated in RFC 6961 section 2.2:
             * If OCSP is not enabled or the client receives a "ocsp_response_list"
             * that does not contain a response for one or more of the certificates
             * in the completed certificate chain, the client SHOULD attempt to
             * validate the certificate using an alternative retrieval method,
             * such as downloading the relevant CRL;
             */
            if (crl_check_all_enabled || (crl_check_enabled && i == 0)) {
                ok = check_cert_crl(ctx);
                if (!ok)
                    return ok;
            } else {
                ok = verify_cb_ocsp(ctx, X509_V_ERR_OCSP_VERIFY_FAILED);
                if (!ok)
                    return ok;
            }
        }
#endif
    }

    if (crl_check_enabled && !ocsp_check_all_enabled) {
        /* certificate status check with CRLs */
        if (crl_check_all_enabled) {
            last = sk_X509_num(ctx->chain) - 1;
        } else {
            /* If checking CRL paths this isn't the EE certificate */
            if (ctx->parent != NULL)
                return 1;
            last = 0;
        }

        /*
         * in the case that OCSP is only enabled for the server certificate
         * and CRL for the complete chain, the rest of the chain has to be
         * checked here
         */
        if (ocsp_check_enabled && crl_check_all_enabled)
            i = 1;
        else
            i = 0;
        for (; i <= last; i++) {
            ctx->error_depth = i;
            ok = check_cert_crl(ctx);
            if (!ok)
                return ok;
        }
    }

    return 1;
}

int ossl_cms_RecipientInfo_pwri_crypt(const CMS_ContentInfo *cms,
    CMS_RecipientInfo *ri, int en_de)
{
    CMS_EncryptedContentInfo *ec;
    CMS_PasswordRecipientInfo *pwri;
    int r = 0;
    X509_ALGOR *algtmp, *kekalg = NULL;
    EVP_CIPHER_CTX *kekctx = NULL;
    char name[OSSL_MAX_NAME_SIZE];
    EVP_CIPHER *kekcipher;
    unsigned char *key = NULL;
    size_t keylen;
    const CMS_CTX *cms_ctx = ossl_cms_get0_cmsctx(cms);

    ec = ossl_cms_get0_env_enc_content(cms);

    pwri = ri->d.pwri;

    if (pwri->pass == NULL) {
        ERR_raise(ERR_LIB_CMS, CMS_R_NO_PASSWORD);
        return 0;
    }
    algtmp = pwri->keyEncryptionAlgorithm;

    if (!algtmp || OBJ_obj2nid(algtmp->algorithm) != NID_id_alg_PWRI_KEK) {
        ERR_raise(ERR_LIB_CMS, CMS_R_UNSUPPORTED_KEY_ENCRYPTION_ALGORITHM);
        return 0;
    }

    kekalg = ASN1_TYPE_unpack_sequence(ASN1_ITEM_rptr(X509_ALGOR),
        algtmp->parameter);

    if (kekalg == NULL) {
        ERR_raise(ERR_LIB_CMS, CMS_R_INVALID_KEY_ENCRYPTION_PARAMETER);
        return 0;
    }

    OBJ_obj2txt(name, sizeof(name), kekalg->algorithm, 0);
    kekcipher = EVP_CIPHER_fetch(ossl_cms_ctx_get0_libctx(cms_ctx), name,
        ossl_cms_ctx_get0_propq(cms_ctx));

    if (kekcipher == NULL) {
        ERR_raise(ERR_LIB_CMS, CMS_R_UNKNOWN_CIPHER);
        goto err;
    }

    kekctx = EVP_CIPHER_CTX_new();
    if (kekctx == NULL) {
        ERR_raise(ERR_LIB_CMS, ERR_R_EVP_LIB);
        goto err;
    }
    /* Fixup cipher based on AlgorithmIdentifier to set IV etc */
    if (!EVP_CipherInit_ex(kekctx, kekcipher, NULL, NULL, NULL, en_de))
        goto err;
    EVP_CIPHER_CTX_set_padding(kekctx, 0);
    if (EVP_CIPHER_asn1_to_param(kekctx, kekalg->parameter) <= 0) {
        ERR_raise(ERR_LIB_CMS, CMS_R_CIPHER_PARAMETER_INITIALISATION_ERROR);
        goto err;
    }

    algtmp = pwri->keyDerivationAlgorithm;

    if (algtmp == NULL) {
        ERR_raise(ERR_LIB_CMS, CMS_R_INVALID_KEY_ENCRYPTION_PARAMETER);
        goto err;
    }

    /* Finish password based key derivation to setup key in "ctx" */

    if (!EVP_PBE_CipherInit_ex(algtmp->algorithm,
            (char *)pwri->pass, (int)pwri->passlen,
            algtmp->parameter, kekctx, en_de,
            cms_ctx->libctx, cms_ctx->propq)) {
        ERR_raise(ERR_LIB_CMS, ERR_R_EVP_LIB);
        goto err;
    }

    /* Finally wrap/unwrap the key */

    if (en_de) {

        if (!kek_wrap_key(NULL, &keylen, ec->key, ec->keylen, kekctx, cms_ctx))
            goto err;

        key = OPENSSL_malloc(keylen);

        if (key == NULL)
            goto err;

        if (!kek_wrap_key(key, &keylen, ec->key, ec->keylen, kekctx, cms_ctx))
            goto err;
        pwri->encryptedKey->data = key;
        pwri->encryptedKey->length = (int)keylen;
    } else {
        key = OPENSSL_malloc(pwri->encryptedKey->length);
        if (key == NULL)
            goto err;
        if (!kek_unwrap_key(key, &keylen,
                pwri->encryptedKey->data,
                pwri->encryptedKey->length, kekctx)) {
            ERR_raise(ERR_LIB_CMS, CMS_R_UNWRAP_FAILURE);
            goto err;
        }

        OPENSSL_clear_free(ec->key, ec->keylen);
        ec->key = key;
        ec->keylen = keylen;
    }

    r = 1;

err:
    EVP_CIPHER_free(kekcipher);
    EVP_CIPHER_CTX_free(kekctx);

    if (!r)
        OPENSSL_free(key);
    X509_ALGOR_free(kekalg);

    return r;
}

unsigned char *OSSL_CRMF_ENCRYPTEDVALUE_decrypt(const OSSL_CRMF_ENCRYPTEDVALUE *enc,
    OSSL_LIB_CTX *libctx, const char *propq,
    EVP_PKEY *pkey, int *outlen)
{
    EVP_CIPHER_CTX *evp_ctx = NULL; /* context for symmetric encryption */
    unsigned char *ek = NULL; /* decrypted symmetric encryption key */
    size_t eksize = 0; /* size of decrypted symmetric encryption key */
    EVP_CIPHER *cipher = NULL; /* used cipher */
    int cikeysize = 0; /* key size from cipher */
    unsigned char *iv = NULL; /* initial vector for symmetric encryption */
    unsigned char *out = NULL; /* decryption output buffer */
    int n, ret = 0;
    EVP_PKEY_CTX *pkctx = NULL; /* private key context */
    char name[OSSL_MAX_NAME_SIZE];

    if (outlen == NULL) {
        ERR_raise(ERR_LIB_CRMF, CRMF_R_NULL_ARGUMENT);
        return NULL;
    }
    *outlen = 0;
    if (enc == NULL || enc->symmAlg == NULL || enc->encSymmKey == NULL
        || enc->encValue == NULL || pkey == NULL) {
        ERR_raise(ERR_LIB_CRMF, CRMF_R_NULL_ARGUMENT);
        return NULL;
    }

    /* select symmetric cipher based on algorithm given in message */
    OBJ_obj2txt(name, sizeof(name), enc->symmAlg->algorithm, 0);
    cipher = EVP_CIPHER_fetch(libctx, name, propq);
    if (cipher == NULL) {
        ERR_raise(ERR_LIB_CRMF, CRMF_R_UNSUPPORTED_CIPHER);
        goto end;
    }

    cikeysize = EVP_CIPHER_get_key_length(cipher);
    /* first the symmetric key needs to be decrypted */
    pkctx = EVP_PKEY_CTX_new_from_pkey(libctx, pkey, propq);
    if (pkctx != NULL && EVP_PKEY_decrypt_init(pkctx) > 0) {
        ASN1_BIT_STRING *encKey = enc->encSymmKey;
        size_t failure;
        int retval;

        if (EVP_PKEY_decrypt(pkctx, NULL, &eksize,
                encKey->data, encKey->length)
                <= 0
            || (ek = OPENSSL_malloc(eksize)) == NULL)
            goto end;
        retval = EVP_PKEY_decrypt(pkctx, ek, &eksize, encKey->data, encKey->length);
        failure = ~constant_time_is_zero_s(constant_time_msb(retval)
            | constant_time_is_zero(retval));
        failure |= ~constant_time_eq_s(eksize, (size_t)cikeysize);
        if (failure) {
            ERR_clear_error(); /* error state may have sensitive information */
            ERR_raise(ERR_LIB_CRMF, CRMF_R_ERROR_DECRYPTING_SYMMETRIC_KEY);
            goto end;
        }
    } else {
        goto end;
    }
    if ((iv = OPENSSL_malloc(EVP_CIPHER_get_iv_length(cipher))) == NULL)
        goto end;
    if (enc->symmAlg->parameter == NULL
        || ASN1_TYPE_get_octetstring(enc->symmAlg->parameter, iv,
            EVP_CIPHER_get_iv_length(cipher))
        != EVP_CIPHER_get_iv_length(cipher)) {
        ERR_raise(ERR_LIB_CRMF, CRMF_R_MALFORMED_IV);
        goto end;
    }

    if ((out = OPENSSL_malloc(enc->encValue->length + EVP_CIPHER_get_block_size(cipher))) == NULL
        || (evp_ctx = EVP_CIPHER_CTX_new()) == NULL)
        goto end;
    EVP_CIPHER_CTX_set_padding(evp_ctx, 0);

    if (!EVP_DecryptInit(evp_ctx, cipher, ek, iv)
        || !EVP_DecryptUpdate(evp_ctx, out, outlen,
            enc->encValue->data,
            enc->encValue->length)
        || !EVP_DecryptFinal(evp_ctx, out + *outlen, &n)) {
        ERR_raise(ERR_LIB_CRMF, CRMF_R_ERROR_DECRYPTING_ENCRYPTEDVALUE);
        goto end;
    }
    *outlen += n;
    ret = 1;

end:
    EVP_PKEY_CTX_free(pkctx);
    EVP_CIPHER_CTX_free(evp_ctx);
    EVP_CIPHER_free(cipher);
    OPENSSL_clear_free(ek, eksize);
    OPENSSL_free(iv);
    if (ret)
        return out;
    OPENSSL_free(out);
    return NULL;
}

static int cms_RecipientInfo_ktri_decrypt(CMS_ContentInfo *cms,
    CMS_RecipientInfo *ri)
{
    CMS_KeyTransRecipientInfo *ktri = ri->d.ktri;
    EVP_PKEY *pkey = ktri->pkey;
    unsigned char *ek = NULL;
    size_t eklen;
    int ret = 0;
    size_t fixlen = 0;
    const EVP_CIPHER *cipher = NULL;
    EVP_CIPHER *fetched_cipher = NULL;
    CMS_EncryptedContentInfo *ec;
    const CMS_CTX *ctx = ossl_cms_get0_cmsctx(cms);
    OSSL_LIB_CTX *libctx = ossl_cms_ctx_get0_libctx(ctx);
    const char *propq = ossl_cms_ctx_get0_propq(ctx);

    ec = ossl_cms_get0_env_enc_content(cms);

    if (ktri->pkey == NULL) {
        ERR_raise(ERR_LIB_CMS, CMS_R_NO_PRIVATE_KEY);
        return 0;
    }

    if (cms->d.envelopedData->encryptedContentInfo->havenocert
        && !cms->d.envelopedData->encryptedContentInfo->debug) {
        X509_ALGOR *calg = ec->contentEncryptionAlgorithm;
        char name[OSSL_MAX_NAME_SIZE];

        OBJ_obj2txt(name, sizeof(name), calg->algorithm, 0);

        (void)ERR_set_mark();
        fetched_cipher = EVP_CIPHER_fetch(libctx, name, propq);

        if (fetched_cipher != NULL)
            cipher = fetched_cipher;
        else
            cipher = EVP_get_cipherbyobj(calg->algorithm);
        if (cipher == NULL) {
            (void)ERR_clear_last_mark();
            ERR_raise(ERR_LIB_CMS, CMS_R_UNKNOWN_CIPHER);
            return 0;
        }
        (void)ERR_pop_to_mark();

        fixlen = EVP_CIPHER_get_key_length(cipher);
        EVP_CIPHER_free(fetched_cipher);
    }

    ktri->pctx = EVP_PKEY_CTX_new_from_pkey(libctx, pkey, propq);
    if (ktri->pctx == NULL)
        goto err;

    if (EVP_PKEY_decrypt_init(ktri->pctx) <= 0)
        goto err;

    if (!ossl_cms_env_asn1_ctrl(ri, 1))
        goto err;

    if (evp_pkey_decrypt_alloc(ktri->pctx, &ek, &eklen, fixlen,
            ktri->encryptedKey->data,
            ktri->encryptedKey->length)
        <= 0)
        goto err;

    ret = 1;

    OPENSSL_clear_free(ec->key, ec->keylen);
    ec->key = ek;
    ec->keylen = eklen;

err:
    EVP_PKEY_CTX_free(ktri->pctx);
    ktri->pctx = NULL;
    if (!ret)
        OPENSSL_free(ek);

    return ret;
}

static int
verify_ss_cert_trans(OSSL_CMP_CTX *ctx, X509 *trusted /* may be NULL */,
    X509 *trans /* the only untrusted cert, may be NULL */,
    X509 *target, const char *desc)
{
    X509_STORE *ts = OSSL_CMP_CTX_get0_trusted(ctx);
    STACK_OF(X509) *untrusted = NULL;
    int res = 0;

    if (trusted != NULL) {
        X509_VERIFY_PARAM *vpm = X509_STORE_get0_param(ts);

        if ((ts = X509_STORE_new()) == NULL)
            return 0;
        if (!X509_STORE_set1_param(ts, vpm)
            || !X509_STORE_add_cert(ts, trusted))
            goto err;
    }

    if (trans != NULL && trans != target
        && !ossl_x509_add_cert_new(&untrusted, trans, X509_ADD_FLAG_UP_REF))
        goto err;

    res = verify_ss_cert(OSSL_CMP_CTX_get0_libctx(ctx),
        OSSL_CMP_CTX_get0_propq(ctx),
        ts, untrusted, target);
    if (!res)
        ERR_raise_data(ERR_LIB_CMP, CMP_R_INVALID_ROOTCAKEYUPDATE,
            "failed to validate %s certificate received in genp %s",
            desc, trusted == NULL ? "using trust store" : "with given certificate as trust anchor");

err:
    sk_X509_pop_free(untrusted, X509_free);
    if (trusted != NULL)
        X509_STORE_free(ts);
    return res;
}

static int dh_match_params(DH *priv, DH *peer)
{
    int ret;
    FFC_PARAMS *dhparams_priv = ossl_dh_get0_params(priv);
    FFC_PARAMS *dhparams_peer = ossl_dh_get0_params(peer);

    ret = dhparams_priv != NULL
        && dhparams_peer != NULL
        && ossl_ffc_params_cmp(dhparams_priv, dhparams_peer, 1)
        && BN_cmp(dhparams_priv->q, dhparams_peer->q) == 0;
    if (!ret)
        ERR_raise(ERR_LIB_PROV, PROV_R_MISMATCHING_DOMAIN_PARAMETERS);
    return ret;
}

static int validate_email_name(const char *name, size_t len, int rfc822)
{
    size_t dns_len, local_len;
    const char *at, *next, *dnsname;
    ossl_charset_t local_charset;

    /*
     * 64 for local part, 1 for @, 255 for domain name
     */
    if (len > 320)
        goto err;

    /* Reject it if there is no @ */
    if ((at = memchr(name, '@', len)) == NULL)
        goto err;

    /* Go to the last @ */
    while ((next = memchr(at + 1, '@', len - (at - name + 1))) != NULL)
        at = next;

    /* Ensure the local part is not oversize */
    local_len = at - name;
    if (local_len > 64)
        goto err;

    if (!validate_local_part(name, local_len, &local_charset))
        goto err;

    if (rfc822 && local_charset == OSSL_CHARSET_NONASCII)
        goto err;

    if (!rfc822 && local_charset == OSSL_CHARSET_ASCII)
        goto err;

    /* What is after the @ must be valid as a dns name */
    dnsname = at + 1;
    dns_len = len - local_len - 1;

    if (rfc822)
        return validate_hostname_part(dnsname, dns_len, OSSL_CHARSET_ASCII_ALNUM);

    return validate_hostname_part(dnsname, dns_len, OSSL_CHARSET_NONASCII);

err:
    ERR_raise(ERR_LIB_X509, ERR_R_PASSED_INVALID_ARGUMENT);
    return 0;
}

static int read_internal(QUIC_RSTREAM *qrs, unsigned char *buf, size_t size,
    size_t *readbytes, int *fin, int drop)
{
    void *iter = NULL;
    UINT_RANGE range;
    const unsigned char *data;
    uint64_t offset = 0;
    size_t readbytes_ = 0;
    int fin_ = 0, ret = 1;

    iter = NULL;
    while (ossl_sframe_list_peek(&qrs->fl, &iter, &range, &data, &fin_)) {
        size_t l = (size_t)(range.end - range.start);

        if (l > size) {
            l = size;
            fin_ = 0;
        }
        offset = range.start + l;
        if (l == 0)
            break;

        if (data == NULL) {
            size_t max_len;

            data = ring_buf_get_ptr(&qrs->rbuf, range.start, &max_len);
            if (!ossl_assert(data != NULL))
                return 0;
            if (max_len < l) {
                memcpy(buf, data, max_len);
                size -= max_len;
                buf += max_len;
                readbytes_ += max_len;
                l -= max_len;
                data = ring_buf_get_ptr(&qrs->rbuf, range.start + max_len,
                    &max_len);
                if (!ossl_assert(data != NULL) || !ossl_assert(max_len > l))
                    return 0;
            }
        }

        memcpy(buf, data, l);
        size -= l;
        buf += l;
        readbytes_ += l;
        if (size == 0)
            break;
    }

    if (drop && offset != 0) {
        ret = ossl_sframe_list_drop_frames(&qrs->fl, offset);
        ring_buf_cpop_range(&qrs->rbuf, 0, offset - 1, qrs->fl.cleanse);
    }

    if (ret) {
        *readbytes = readbytes_;
        *fin = fin_;
    }

    return ret;
}

static int aes_ocb_cipher(void *vctx, unsigned char *out, size_t *outl,
    size_t outsize, const unsigned char *in, size_t inl)
{
    PROV_AES_OCB_CTX *ctx = (PROV_AES_OCB_CTX *)vctx;

    if (!ossl_prov_is_running())
        return 0;

    if (outsize < inl) {
        ERR_raise(ERR_LIB_PROV, PROV_R_OUTPUT_BUFFER_TOO_SMALL);
        return 0;
    }

    if (ctx->iv_set == 0) {
        if (!aes_ocb_set_iv(ctx)) {
            ERR_raise(ERR_LIB_PROV, PROV_R_CIPHER_OPERATION_FAILED);
            return 0;
        }
        ctx->iv_set = 1;
    }

    if (!aes_generic_ocb_cipher(ctx, in, out, inl)) {
        ERR_raise(ERR_LIB_PROV, PROV_R_CIPHER_OPERATION_FAILED);
        return 0;
    }

    *outl = inl;
    return 1;
}

static int aes_gcm_siv_initkey(void *vctx)
{
    PROV_AES_GCM_SIV_CTX *ctx = (PROV_AES_GCM_SIV_CTX *)vctx;
    uint8_t output[BLOCK_SIZE];
    uint32_t counter = 0x0;
    size_t i;
    union {
        uint32_t counter;
        uint8_t block[BLOCK_SIZE];
    } data;
    int out_len;
    EVP_CIPHER *ecb = NULL;
    DECLARE_IS_ENDIAN;

    switch (ctx->key_len) {
    case 16:
        ecb = EVP_CIPHER_fetch(ctx->libctx, "AES-128-ECB", NULL);
        break;
    case 24:
        ecb = EVP_CIPHER_fetch(ctx->libctx, "AES-192-ECB", NULL);
        break;
    case 32:
        ecb = EVP_CIPHER_fetch(ctx->libctx, "AES-256-ECB", NULL);
        break;
    default:
        goto err;
    }

    if (ctx->ecb_ctx == NULL && (ctx->ecb_ctx = EVP_CIPHER_CTX_new()) == NULL)
        goto err;
    if (!EVP_EncryptInit_ex2(ctx->ecb_ctx, ecb, ctx->key_gen_key, NULL, NULL))
        goto err;

    memset(&data, 0, sizeof(data));
    memcpy(&data.block[sizeof(data.counter)], ctx->nonce, NONCE_SIZE);

    /* msg_auth_key is always 16 bytes in size, regardless of AES128/AES256 */
    /* counter is stored little-endian */
    for (i = 0; i < BLOCK_SIZE; i += 8) {
        if (IS_LITTLE_ENDIAN) {
            data.counter = counter;
        } else {
            data.counter = GSWAP4(counter);
        }
        /* Block size is 16 (128 bits), but only 8 bytes are used */
        out_len = BLOCK_SIZE;
        if (!EVP_EncryptUpdate(ctx->ecb_ctx, output, &out_len, data.block, BLOCK_SIZE))
            goto err;
        memcpy(&ctx->msg_auth_key[i], output, 8);
        counter++;
    }

    /* msg_enc_key length is directly tied to key length AES128/AES256 */
    for (i = 0; i < ctx->key_len; i += 8) {
        if (IS_LITTLE_ENDIAN) {
            data.counter = counter;
        } else {
            data.counter = GSWAP4(counter);
        }
        /* Block size is 16 bytes (128 bits), but only 8 bytes are used */
        out_len = BLOCK_SIZE;
        if (!EVP_EncryptUpdate(ctx->ecb_ctx, output, &out_len, data.block, BLOCK_SIZE))
            goto err;
        memcpy(&ctx->msg_enc_key[i], output, 8);
        counter++;
    }

    if (!EVP_EncryptInit_ex2(ctx->ecb_ctx, ecb, ctx->msg_enc_key, NULL, NULL))
        goto err;

    /* Freshen up the state */
    ctx->used_enc = 0;
    ctx->used_dec = 0;
    memset(ctx->tag, 0, BLOCK_SIZE);
    EVP_CIPHER_free(ecb);
    return 1;
err:
    EVP_CIPHER_CTX_free(ctx->ecb_ctx);
    EVP_CIPHER_free(ecb);
    ctx->ecb_ctx = NULL;
    return 0;
}

enum XML_Status XMLCALL
XML_ResumeParser(XML_Parser parser) {
  enum XML_Status result = XML_STATUS_OK;

  if (parser == NULL)
    return XML_STATUS_ERROR;
  if (parser->m_parsingStatus.parsing != XML_SUSPENDED) {
    parser->m_errorCode = XML_ERROR_NOT_SUSPENDED;
    return XML_STATUS_ERROR;
  }

  if (parser->m_handlerCallDepth != 0) {
    parser->m_errorCode = XML_ERROR_RECURSIVE_ENTITY_REF;
    return XML_STATUS_ERROR;
  }

  parser->m_parsingStatus.parsing = XML_PARSING;

  parser->m_errorCode = callProcessor(
      parser, parser->m_bufferPtr, parser->m_parseEndPtr, &parser->m_bufferPtr);

  if (parser->m_errorCode != XML_ERROR_NONE) {
    parser->m_eventEndPtr = parser->m_eventPtr;
    parser->m_processor = errorProcessor;
    return XML_STATUS_ERROR;
  } else {
    switch (parser->m_parsingStatus.parsing) {
    case XML_SUSPENDED:
      result = XML_STATUS_SUSPENDED;
      break;
    case XML_INITIALIZED:
    case XML_PARSING:
      if (parser->m_parsingStatus.finalBuffer) {
        parser->m_parsingStatus.parsing = XML_FINISHED;
        return result;
      }
      break;
    default:;
    }
  }

  XmlUpdatePosition(parser->m_encoding, parser->m_positionPtr,
                    parser->m_bufferPtr, &parser->m_position);
  parser->m_positionPtr = parser->m_bufferPtr;
  return result;
}

static int keep_schunk_data_on_packet(SFRAME_SET *fs, OSSL_QRX_PKT *pkt,
    UINT_RANGE *r)
{
    /*
     * the function decides whether stream data should be moved
     * from packet buffer to stream buffer or if data can stay
     * at packet buffer.
     *
     * Keeping the data at packet saves yet another buffer
     * allocation at heap (+ data transfer). On the other hand
     * it opens door to malicious peer to force stack to use more
     * memory than necessary.
     *
     * The function here should asses a current stream quality:
     *   how many stream chunks are there
     *   the time elapsed since the arrival of earlier chunk
     *   the time elapsed since the application consumed the data
     *   the size of the chunk compared with the whole packet size
     *   the size of chunk with respect to DIRECT_STORAGE_SZ
     *   ...
     */

    uint64_t frame_size, packet_size, overhead;

    if (fs == NULL || pkt == NULL || r == NULL)
        return 0;

    /* Calculate the size of the stream frame data */
    frame_size = r->end - r->start;

    /* Calculate the size of the whole packet */
    packet_size = pkt->data_len;

    /* Calculate memory overhead for this frame */
    if (packet_size > frame_size)
        overhead = packet_size - frame_size;
    else
        overhead = 0;

    /* Add to cumulative overhead for this stream */
    fs->cumulative_overhead += overhead;

    /* If cumulative overhead exceeds 64kB, move data to stream buffer */
    if (fs->cumulative_overhead > 65536)
        return 0;

    return 1;
}

static int dtls_rlayer_buffer_record(OSSL_RECORD_LAYER *rl, struct pqueue_st *queue,
    unsigned char *priority)
{
    DTLS_RLAYER_RECORD_DATA *rdata;
    pitem *item;

    /* Limit the size of the queue to prevent DOS attacks */
    if (pqueue_size(queue) >= 100)
        return 0;

    rdata = OPENSSL_malloc(sizeof(*rdata));
    item = pitem_new(priority, rdata);
    if (rdata == NULL || item == NULL) {
        OPENSSL_free(rdata);
        pitem_free(item);
        RLAYERfatal(rl, SSL_AD_INTERNAL_ERROR, ERR_R_INTERNAL_ERROR);
        return -1;
    }

    /* Only allocate and copy the actual packet data, not the entire buffer */
    rdata->packet = OPENSSL_memdup(rl->packet, rl->packet_length);
    rdata->packet_length = rl->packet_length;
    if (rdata->packet == NULL && rl->packet_length > 0) {
        OPENSSL_free(rdata);
        pitem_free(item);
        RLAYERfatal(rl, SSL_AD_INTERNAL_ERROR, ERR_R_INTERNAL_ERROR);
        return -1;
    }

    memcpy(&(rdata->rbuf), &rl->rbuf, sizeof(TLS_BUFFER));
    memcpy(&(rdata->rrec), &rl->rrec[0], sizeof(TLS_RL_RECORD));

    item->data = rdata;

    rl->packet = NULL;
    rl->packet_length = 0;
    memset(&rl->rbuf, 0, sizeof(TLS_BUFFER));
    memset(&rl->rrec[0], 0, sizeof(rl->rrec[0]));

    if (!tls_setup_read_buffer(rl)) {
        /* RLAYERfatal() already called */
        OPENSSL_free(rdata->packet);
        OPENSSL_free(rdata->rbuf.buf);
        OPENSSL_free(rdata);
        pitem_free(item);
        return -1;
    }

    if (pqueue_insert(queue, item) == NULL) {
        /* Must be a duplicate so ignore it */
        OPENSSL_free(rdata->packet);
        OPENSSL_free(rdata->rbuf.buf);
        OPENSSL_free(rdata);
        pitem_free(item);
    }

    return 1;
}

static void ecp_sm2p256_point_add(P256_POINT *R, const P256_POINT *P,
    const P256_POINT *Q)
{
    unsigned int i;
    ALIGN32 BN_ULONG tmp0[P256_LIMBS] = { 0 };
    ALIGN32 BN_ULONG tmp1[P256_LIMBS] = { 0 };
    ALIGN32 BN_ULONG tmp2[P256_LIMBS] = { 0 };
    ALIGN32 BN_ULONG res_x[P256_LIMBS] = { 0 };
    ALIGN32 BN_ULONG res_y[P256_LIMBS] = { 0 };
    ALIGN32 BN_ULONG res_z[P256_LIMBS] = { 0 };
    ALIGN32 BN_ULONG doubled[P256_LIMBS] = { 0 };
    ALIGN32 BN_ULONG doubled_y[P256_LIMBS] = { 0 };
    ALIGN32 BN_ULONG doubled_z[P256_LIMBS] = { 0 };
    BN_ULONG p_z_is_zero, q_z_is_zero, points_equal;

    /* Perform the full point addition unconditionally */
    ecp_sm2p256_sqr(tmp0, P->Z);
    ecp_sm2p256_mul(tmp1, tmp0, P->Z);
    ecp_sm2p256_mul(tmp0, tmp0, Q->X);
    ecp_sm2p256_mul(tmp1, tmp1, Q->Y);
    ecp_sm2p256_mul(res_y, P->Y, Q->Z);
    ecp_sm2p256_mul(res_z, Q->Z, P->Z);
    ecp_sm2p256_sqr(tmp2, Q->Z);
    ecp_sm2p256_mul(res_y, tmp2, res_y);
    ecp_sm2p256_mul(res_x, tmp2, P->X);
    ecp_sm2p256_sub(tmp0, tmp0, res_x);
    ecp_sm2p256_mul(res_z, tmp0, res_z);
    ecp_sm2p256_sub(tmp1, tmp1, res_y);
    ecp_sm2p256_sqr(tmp2, tmp0);
    ecp_sm2p256_mul(tmp0, tmp0, tmp2);
    ecp_sm2p256_mul(tmp2, tmp2, res_x);
    ecp_sm2p256_sqr(res_x, tmp1);
    ecp_sm2p256_sub(res_x, res_x, tmp2);
    ecp_sm2p256_sub(res_x, res_x, tmp2);
    ecp_sm2p256_sub(res_x, res_x, tmp0);
    ecp_sm2p256_sub(tmp2, tmp2, res_x);
    ecp_sm2p256_mul(tmp2, tmp1, tmp2);
    ecp_sm2p256_mul(tmp0, tmp0, res_y);
    ecp_sm2p256_sub(res_y, tmp2, tmp0);

    /* Perform point doubling unconditionally */
    P256_POINT temp_Q;
    for (i = 0; i < P256_LIMBS; ++i) {
        temp_Q.X[i] = Q->X[i];
        temp_Q.Y[i] = Q->Y[i];
        temp_Q.Z[i] = Q->Z[i];
    }
    ecp_sm2p256_point_double(&temp_Q, &temp_Q);
    for (i = 0; i < P256_LIMBS; ++i) {
        doubled[i] = temp_Q.X[i];
        doubled_y[i] = temp_Q.Y[i];
        doubled_z[i] = temp_Q.Z[i];
    }

    /* Constant-time selection based on conditions */
    p_z_is_zero = is_zeros(P->Z);
    q_z_is_zero = is_zeros(Q->Z);
    points_equal = is_point_equal(P, Q);

    /* If P->Z is zero, use Q */
    for (i = 0; i < P256_LIMBS; ++i) {
        R->X[i] = (p_z_is_zero ? Q->X[i] : res_x[i]);
        R->Y[i] = (p_z_is_zero ? Q->Y[i] : res_y[i]);
        R->Z[i] = (p_z_is_zero ? Q->Z[i] : res_z[i]);
    }

    /* If Q->Z is zero, use P */
    for (i = 0; i < P256_LIMBS; ++i) {
        R->X[i] = (q_z_is_zero ? P->X[i] : R->X[i]);
        R->Y[i] = (q_z_is_zero ? P->Y[i] : R->Y[i]);
        R->Z[i] = (q_z_is_zero ? P->Z[i] : R->Z[i]);
    }

    /* If points are equal, use doubled result */
    for (i = 0; i < P256_LIMBS; ++i) {
        R->X[i] = (points_equal ? doubled[i] : R->X[i]);
        R->Y[i] = (points_equal ? doubled_y[i] : R->Y[i]);
        R->Z[i] = (points_equal ? doubled_z[i] : R->Z[i]);
    }
}

const mbfl_encoding *mbfl_name2encoding_ex(const char *name, size_t name_len)
{
	const mbfl_encoding *const *encoding;

	/* Sanity check perfect hash for name.
	 * Never enable this in production, this is only a development-time sanity check! */
#if ZEND_DEBUG && 0
	for (encoding = mbfl_encoding_ptr_list; *encoding; encoding++) {
		size_t name_length = strlen((*encoding)->name);
		if (!(name_length <= NAME_HASH_MAX_NAME_LENGTH && name_length >= NAME_HASH_MIN_NAME_LENGTH)) {
			fprintf(stderr, "name length is not satisfying bound check: %zu %s\n", name_length, (*encoding)->name);
			abort();
		}
		unsigned int key = mbfl_name2encoding_perfect_hash((*encoding)->name, name_length);
		if (mbfl_encoding_ptr_list[mbfl_encoding_ptr_list_after_hashing[key]] != *encoding) {
			fprintf(stderr, "mbfl_name2encoding_perfect_hash: key %u %s mismatch\n", key, (*encoding)->name);
			abort();
		}
	}
#endif

	/* Use perfect hash lookup for name */
	if (name_len <= NAME_HASH_MAX_NAME_LENGTH && name_len >= NAME_HASH_MIN_NAME_LENGTH) {
		unsigned int key = mbfl_name2encoding_perfect_hash(name, name_len);
		if (key < sizeof(mbfl_encoding_ptr_list_after_hashing) / sizeof(mbfl_encoding_ptr_list_after_hashing[0])) {
			int8_t offset = mbfl_encoding_ptr_list_after_hashing[key];
			if (offset >= 0) {
				encoding = mbfl_encoding_ptr_list + offset;
				if (strncasecmp((*encoding)->name, name, name_len) == 0 && (*encoding)->name[name_len] == '\0') {
					return *encoding;
				}
			}
		}
	}

	/* search MIME charset name */
	for (encoding = mbfl_encoding_ptr_list; *encoding; encoding++) {
		if ((*encoding)->mime_name) {
			if (strncasecmp((*encoding)->mime_name, name, name_len) == 0 && (*encoding)->mime_name[name_len] == '\0') {
				return *encoding;
			}
		}
	}

	/* search aliases */
	for (encoding = mbfl_encoding_ptr_list; *encoding; encoding++) {
		if ((*encoding)->aliases) {
			for (const char **alias = (*encoding)->aliases; *alias; alias++) {
				if (strncasecmp(name, *alias, name_len) == 0 && (*alias)[name_len] == '\0') {
					return *encoding;
				}
			}
		}
	}

	return NULL;
}

ASN1_BIT_STRING *ossl_cmp_calc_protection(const OSSL_CMP_CTX *ctx,
    const OSSL_CMP_MSG *msg)
{
    ASN1_BIT_STRING *prot = NULL;
    OSSL_CMP_PROTECTEDPART prot_part;
    const ASN1_OBJECT *algorOID = NULL;
    const void *ppval = NULL;
    int pptype = 0;

    if (!ossl_assert(ctx != NULL && msg != NULL))
        return NULL;

    /* construct data to be signed */
    prot_part.header = msg->header;
    prot_part.body = msg->body;

    if (msg->header->protectionAlg == NULL) {
        ERR_raise(ERR_LIB_CMP, CMP_R_UNKNOWN_ALGORITHM_ID);
        return NULL;
    }
    X509_ALGOR_get0(&algorOID, &pptype, &ppval, msg->header->protectionAlg);

    if (OBJ_obj2nid(algorOID) == NID_id_PasswordBasedMAC) {
        int len;
        size_t prot_part_der_len;
        unsigned char *prot_part_der = NULL;
        size_t sig_len;
        unsigned char *protection = NULL;
        OSSL_CRMF_PBMPARAMETER *pbm = NULL;
        ASN1_STRING *pbm_str = NULL;
        const unsigned char *pbm_str_uc = NULL;

        if (ctx->secretValue == NULL) {
            ERR_raise(ERR_LIB_CMP, CMP_R_MISSING_PBM_SECRET);
            return NULL;
        }
        if (ppval == NULL || pptype != V_ASN1_SEQUENCE) {
            ERR_raise(ERR_LIB_CMP, CMP_R_ERROR_CALCULATING_PROTECTION);
            return NULL;
        }

        len = i2d_OSSL_CMP_PROTECTEDPART(&prot_part, &prot_part_der);
        if (len < 0 || prot_part_der == NULL) {
            ERR_raise(ERR_LIB_CMP, CMP_R_ERROR_CALCULATING_PROTECTION);
            goto end;
        }
        prot_part_der_len = (size_t)len;

        pbm_str = (ASN1_STRING *)ppval;
        pbm_str_uc = ASN1_STRING_get0_data(pbm_str);
        if (ASN1_STRING_get_length(pbm_str) > INT_MAX) {
            ERR_raise(ERR_LIB_CMP, CMP_R_WRONG_ALGORITHM_OID);
            goto end;
        }
        pbm = d2i_OSSL_CRMF_PBMPARAMETER(NULL, &pbm_str_uc, (long)ASN1_STRING_get_length(pbm_str));
        if (pbm == NULL) {
            ERR_raise(ERR_LIB_CMP, CMP_R_WRONG_ALGORITHM_OID);
            goto end;
        }

        if (!OSSL_CRMF_pbm_new(ctx->libctx, ctx->propq,
                pbm, prot_part_der, prot_part_der_len,
                ASN1_STRING_get0_data(ctx->secretValue), ASN1_STRING_get_length(ctx->secretValue),
                &protection, &sig_len))
            goto end;

        if (sig_len > INT_MAX || (prot = ASN1_BIT_STRING_new()) == NULL)
            goto end;
        /* OpenSSL by default encodes all bit strings as ASN.1 NamedBitList */
        if (!ASN1_BIT_STRING_set1(prot, protection, (int)sig_len, 0)) {
            ASN1_BIT_STRING_free(prot);
            prot = NULL;
        }
    end:
        OSSL_CRMF_PBMPARAMETER_free(pbm);
        OPENSSL_free(protection);
        OPENSSL_free(prot_part_der);
        return prot;
    } else {
        const EVP_MD *md = ctx->digest;
        char name[80] = "";

        if (ctx->pkey == NULL) {
            ERR_raise(ERR_LIB_CMP,
                CMP_R_MISSING_KEY_INPUT_FOR_CREATING_PROTECTION);
            return NULL;
        }
        if (EVP_PKEY_get_default_digest_name(ctx->pkey, name, sizeof(name)) > 0
            && strcmp(name, "UNDEF") == 0) /* at least for Ed25519, Ed448 */
            md = NULL;

        if ((prot = ASN1_BIT_STRING_new()) == NULL)
            return NULL;
        if (ASN1_item_sign_ex(ASN1_ITEM_rptr(OSSL_CMP_PROTECTEDPART),
                msg->header->protectionAlg, /* sets X509_ALGOR */
                NULL, prot, &prot_part, NULL, ctx->pkey, md,
                ctx->libctx, ctx->propq)
            != 0)
            return prot;
        ASN1_BIT_STRING_free(prot);
        return NULL;
    }
}

